-- Re-audit fix 1: staff may record/update a call-out only for a shift assigned to themselves (same org); org admins/managers for any shift in their org.
DROP POLICY IF EXISTS "org members update callouts" ON public.shift_callouts;
CREATE POLICY "org members update callouts" ON public.shift_callouts AS PERMISSIVE FOR UPDATE TO authenticated
  USING ((is_org_admin_or_manager(organization_id, auth.uid()) AND EXISTS (SELECT 1 FROM public.scheduled_shifts s WHERE s.id = shift_callouts.scheduled_shift_id AND s.organization_id = shift_callouts.organization_id)) OR (is_org_member(organization_id, auth.uid()) AND staff_id = auth.uid() AND EXISTS (SELECT 1 FROM public.scheduled_shifts s WHERE s.id = shift_callouts.scheduled_shift_id AND s.organization_id = shift_callouts.organization_id AND s.staff_id = auth.uid())))
  WITH CHECK ((is_org_admin_or_manager(organization_id, auth.uid()) AND EXISTS (SELECT 1 FROM public.scheduled_shifts s WHERE s.id = shift_callouts.scheduled_shift_id AND s.organization_id = shift_callouts.organization_id)) OR (is_org_member(organization_id, auth.uid()) AND staff_id = auth.uid() AND EXISTS (SELECT 1 FROM public.scheduled_shifts s WHERE s.id = shift_callouts.scheduled_shift_id AND s.organization_id = shift_callouts.organization_id AND s.staff_id = auth.uid())));
